pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // First send to increment depositsCount to 1 (avoids overflow on first call)
        vm.deal(address(this), 1 wei);
        c.sendMoney{value: 1 wei}(address(c), 1 wei, "");
        // depositsCount becomes 1
        uint val = type(uint).max - 1;
        for (uint i = 0; i < val; i++) {
            vm.deal(address(this), 1 wei);
            c.sendMoney{value: 1 wei}(address(c), 1 wei, "");
        }
        // Now depositsCount should be type(uint).max
        bool ok;
        vm.deal(address(this), 1 wei);
        try c.sendMoney{value: 1 wei}(address(c), 1 wei, "") {
            // Only buggy contract succeeds (wraps to 0)
            ok = true;
        } catch {
            // Reference reverts
            ok = false;
        }
        assertTrue(ok == true); // Bug passes, reference fails
    }
}

