pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund contract with 5 ether
        vm.deal(address(c), 5 ether);
        // Owner (deployer) calls sendMoney to address(1) with 2 ether
        // address(1) is non-payable, so reference: call reverts, contract keeps 5 ether
        // buggy version: owner receives 2 ether, contract balance becomes 3 ether
        address owner = c.owner();
        vm.prank(owner);
        c.sendMoney(address(1), 2 ether, "");
        // After call, check contract balance
        assertTrue(address(c).balance == 5 ether);
    }
}

