pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Target {
    uint public callCount;
    function () external payable {
        if (msg.data.length > 0) {
            callCount++;
        }
    }
}

contract InvMutTest is Test {
    C c;
    Target target;
    function setUp() public { 
        c = new C(); 
        target = new Target();
    }
    function testRegression_property() public {
        // Setup: fund the contract with some ether so it can send
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent, "funding failed");
        // The owner is msg.sender of constructor = address(this)
        // Send money with non-empty _data (just one non-zero byte)
        bytes memory data = hex"01";
        vm.prank(c.owner());
        c.sendMoney(address(target), 0, data);
        // Check the counter on target - reference increments it, bug does not
        uint count = target.callCount();
        assertTrue(count == 1);
    }
}

