pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Receiver {
    fallback(bytes calldata data) external payable returns (bytes memory) {
        if (data.length > 0) {
            revert("data not empty");
        }
    }
}

contract InvMutTest is Test {
    C c;
    Receiver receiver;
    function setUp() public { 
        c = new C(); 
        receiver = new Receiver();
    }
    function testRegression_property() public {
        // Fund the contract owner to send ether
        address owner = c.owner();
        vm.deal(owner, 1 ether);
        vm.prank(owner);

        // Call sendMoney with non-empty data and value 1 wei
        bytes memory data = hex"01";
        c.sendMoney{value: 1 wei}(address(receiver), 1 wei, data);

        // Reference: the buggy contract forwards empty data, call succeeds, ether transferred out
        // Buggy: empty data call succeeds, ether goes out, c.balance = 0
        // Correct: non-empty data causes revert, ether stays in C, c.balance = 1 wei
        assertTrue(c.balanceOf(address(this)) == 1 wei);
    }
}

