pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a helper contract that reverts on empty data calls in its receive/fallback
        // We'll deploy it inline via create2
        TargetReceiver receiver = new TargetReceiver();
        vm.deal(address(c), 2 wei);
        vm.prank(c.owner());
        c.sendMoney(address(receiver), 1 wei, "0x1234");
        // Reference: data forwarded → receiver's fallback sees non-empty data, does nothing, ether sent back? Actually the call reverts? Let's check: The fallback requires non-empty data, so it reverts → the whole sendMoney call reverts? No, the low-level call returns false but does not revert the whole transaction.
        // So in both contracts, the call returns false. However, the difference is in whether the ether is transferred.
        // For reference: call returns false, ether is sent to receiver but then revert returns the ether? Actually in low-level call, if the call reverts, the ether is returned to the caller, so C gets it back. So C.balance stays 2 wei.
        // For bug: empty data → fallback receives empty data, does not revert, so ether stays in receiver. Then C.balance decreases by 1 wei.
        // So after the call, C.balance is 2 wei in reference, 1 wei in bug.
        assertTrue(c.depositsCount() == 0); // just to use a getter
        assertTrue(address(c).balance == 2 wei);
    }
}

contract TargetReceiver {
    receive() external payable {
        require(msg.data.length > 0, "no empty data");
    }
    fallback() external payable {
        require(msg.data.length > 0, "no empty data");
    }
}

