pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple target that tracks calls with data length
        Target t = new Target();
        address targetAddr = address(t);

        // Setup: fund the owner (which is the test contract address because c was deployed by setUp)
        address owner = address(this);
        vm.deal(owner, 1 ether);

        // Call sendMoney with non-empty data to target (1 wei, data = 0x01)
        bytes memory data = hex"01";
        c.sendMoney(targetAddr, 1 wei, data);

        // Assert: in reference, the target received the call with data length 1 (non-empty)
        // In buggy, the target received empty data (length 0) because _data was replaced by ""
        assertTrue(t.lastDataLength() == 1);
    }
}

contract Target {
    uint public lastDataLength;
    receive() external payable {
        lastDataLength = 0;
    }
    fallback() external payable {
        lastDataLength = msg.data.length;
    }
}

