pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up non-owner actor
        address nonOwner = address(0x123);
        vm.deal(nonOwner, 1 ether);

        // Record balance before call
        uint balanceBefore = address(c).balance;

        // Non-owner attempts sendMoney with 0.5 ether
        bool success;
        vm.prank(nonOwner);
        try c.sendMoney{value: 0.5 ether}(nonOwner, 0.5 ether, "") {
            success = true;
        } catch {
            success = false;
        }

        // In reference (correct), call reverts — balance unchanged; in buggy, call succeeds — balance increases by 0.5 ether
        assertTrue(success == false); // true for reference, false for buggy
    }
}

